const types = new Set(['ingredients_photo', 'dish_photo', 'recipe_document', 'not_food']);
let type = String(o.type || '').toLowerCase();
const confidence = Number(o.confidence);
if (!types.has(type)) type = 'not_food';
if (type === 'not_food' && Number.isFinite(confidence) && confidence < 0.6) type = 'ingredients_photo';
return [{json:{type, confidence:Number.isFinite(confidence)?Math.max(0,Math.min(1,confidence)):0, visible:String(o.visible || '').slice(0,120)}}];

const f = $('Webhook').first().json.body.filters || {};
const max_minutes = f.max_minutes || null;
const max_calories = f.max_kcal || null;
const vegetarian = f.vegetarian === true;
const cuisine = f.cuisine || null;
const min_protein = f.min_protein_g || null;

// --- user text from the webhook ---
const userText = String($('Webhook').first().json.body.query || "").trim();
const hasText = userText.length > 0;

const clean = s => String(s || "").toLowerCase().replace(/[^\p{L}\s'-]/gu, " ").replace(/\s+/g, " ").trim();
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}

// --- photo ingredients ---
const seen = new Set(), ing = [], dropped = [];
for (const i of (Array.isArray(o.ingredients) ? o.ingredients : []).slice(0, 25)) {
  const name = clean(i && typeof i === "object" ? i.name : i);
  if (!name || seen.has(name)) continue;
  seen.add(name);
  const c = i && typeof i === "object" && i.confidence !== undefined ? Number(i.confidence) : 1;
  (c >= 0.6 ? ing : dropped).push(name);
}
const uncertain = [...new Set(dropped.concat(Array.isArray(o.uncertain) ? o.uncertain.map(clean) : []).filter(Boolean))];

// --- merge text + photo ---
// Text words become the dish/title query; photo ingredients become user_ingredients.
const title_query = hasText ? clean(userText) : "";
const source = hasText ? "text+photo" : "photo";
const mode = hasText ? "dish" : "ingredients";

const queryParts = [];
if (title_query) queryParts.push(title_query);
if (ing.length) queryParts.push("Ingredients: " + ing.join(", "));
const query = queryParts.join(" | ");

return [{ json: {
  mode, source,
  query, title_query,
  user_ingredients: ing, uncertain,
  max_minutes, max_calories, vegetarian, cuisine, min_protein
} }];

const f = $('Webhook').first().json.body.filters || {};
const max_minutes = f.max_minutes || null;
const max_calories = f.max_kcal || null;
const vegetarian = f.vegetarian === true;
const cuisine = f.cuisine || null;
const min_protein = f.min_protein_g || null;

// --- user text from the webhook ---
const userText = String($('Webhook').first().json.body.query || "").trim();
const hasText = userText.length > 0;

const clean = s => String(s || "").toLowerCase().replace(/[^\p{L}\s'-]/gu, " ").replace(/\s+/g, " ").trim();
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}

// --- photo dish info ---
const photoDish = clean(o.dish || o.title || "");
const visible = clean(o.visible || "");

// --- merge text + photo ---
// Prefer the user's text as the dish; fall back to what the photo shows.
const title_query = hasText ? clean(userText) : photoDish;
const source = hasText ? "text+photo" : "photo";
const mode = "dish";

const queryParts = [];
if (title_query) queryParts.push(title_query);
if (visible && visible !== title_query) queryParts.push("Photo shows: " + visible);
const query = queryParts.join(" | ");

return [{ json: {
  mode, source,
  query, title_query,
  user_ingredients: [],
  uncertain: [],
  max_minutes, max_calories, vegetarian, cuisine, min_protein
} }];

const f = $('Webhook').first().json.body.filters || {};
const sourceText = String($('Webhook').first().json.body.query || '').trim();
let o = {};
try { o = JSON.parse($json.message.content || '{}'); } catch (_) {}
const str = x => x == null ? '' : String(x).trim();
const clean = x => str(x).toLowerCase().replace(/[^\p{L}\p{N}\s'-]/gu, ' ').replace(/\s+/g, ' ').trim();
const arr = x => Array.isArray(x) ? x.filter(v => typeof v === 'string' && v.trim()).map(str).slice(0, 80) : [];
const parsed = {
  title: str(o.title) || null, title_en: str(o.title_en) || null,
  language: str(o.language) || 'unknown', servings: str(o.servings) || null,
  time: str(o.time) || null,
  ingredients: arr(o.ingredients), ingredient_names: arr(o.ingredient_names).map(clean),
  steps: arr(o.steps), complete: o.complete === true
};
const title = clean(sourceText || parsed.title_en || parsed.title || '');
const ingredients = parsed.ingredient_names.slice(0, 20);
const query = [title, ingredients.length ? 'Ingredients: ' + ingredients.join(', ') : ''].filter(Boolean).join(' | ') || (parsed.steps.length ? 'recipe instructions' : '');
return [{ json: {
  mode:'document', source: sourceText ? 'text+photo' : 'photo',
  query, title_query:title, parsed,
  user_ingredients:ingredients, uncertain:[],
  max_minutes:Number(f.max_minutes) > 0 ? Number(f.max_minutes) : null,
  max_calories:Number(f.max_kcal) > 0 ? Number(f.max_kcal) : null,
  vegetarian:f.vegetarian === true, cuisine:f.cuisine || null,
  min_protein:Number(f.min_protein_g) > 0 ? Number(f.min_protein_g) : null
} }];

const body = $('Webhook').first().json.body;
const raw = String(body.query || "").trim();
const f = body.filters || {};
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}

if (!raw || raw.startsWith("/") || o.intent === "help") {
  return [{ json: { mode: "help", source: "text", query: "", user_ingredients: [], uncertain: [],
    max_minutes: null, max_calories: null, vegetarian: false, cuisine: null, min_protein: null } }];
}

const items = [...new Set((Array.isArray(o.items) ? o.items : [])
  .map(x => String(x).toLowerCase().trim()).filter(Boolean))];
// UI filters take priority; LLM-extracted filters are the fallback
const maxMin = f.max_minutes || (Number(o.max_minutes) > 0 ? Number(o.max_minutes) : null);
const maxCal = f.max_kcal || (Number(o.max_calories) > 0 ? Number(o.max_calories) : null);
const veg = f.vegetarian === true || o.vegetarian === true;
const cuisine = f.cuisine || null;
const min_protein = f.min_protein_g || null;

if (o.intent === "ingredients" && items.length) {
  return [{ json: { mode: "ingredients", source: "text", query: "Ingredients: " + items.join(", "), title_query: "",
    user_ingredients: items, uncertain: [], max_minutes: maxMin, max_calories: maxCal, vegetarian: veg,
    cuisine, min_protein } }];
}

const dish = ((o.dish && String(o.dish).trim()) || raw).toLowerCase();
return [{ json: { mode: "text", source: "text", query: dish, title_query: dish, user_ingredients: [], uncertain: [],
  max_minutes: maxMin, max_calories: maxCal, vegetarian: veg, cuisine, min_protein } }];

const n = $('Search context').item.json;
const hits = ($json.result || []).filter(h => h.payload && Array.isArray(h.payload.ingredients));
const doc = n.mode === "document";

const STAPLES = ["salt", "pepper", "black pepper", "white pepper", "water", "hot water", "warm water",
  "cold water", "boiling water", "oil", "vegetable oil", "olive oil", "cooking oil", "cooking spray",
  "sugar", "ice", "ice cubes", "kosher salt", "sea salt", "salt and pepper"];
const stem = w => {
  if (w.length <= 3) return w;
  if (w.endsWith("ies")) return w.slice(0, -3) + "y";
  if (w.endsWith("oes")) return w.slice(0, -2);
  if (w.endsWith("ss")) return w;
  if (w.endsWith("s")) return w.slice(0, -1);
  return w;
};
const toks = s => String(s).toLowerCase().replace(/[^a-z\s]/g, " ").split(/\s+/).filter(Boolean).map(stem);
const STAPLE_KEYS = new Set(STAPLES.map(s => toks(s).join(" ")));
const isStaple = r => STAPLE_KEYS.has(toks(r).join(" "));

const user = (n.user_ingredients || []).map(u => toks(u)).filter(t => t.length);
const matches = (r, u) => {
  const R = toks(r);
  return u.every(t => R.includes(t)) || R.every(t => u.includes(t));
};
const analyse = h => {
  const pantry = [], needed = [];
  h.payload.ingredients.forEach(r => (isStaple(r) ? pantry : needed).push(r));
  const have = needed.filter(r => user.some(u => matches(r, u)));
  const missing = needed.filter(r => !user.some(u => matches(r, u)));
  const usedUser = user.filter(u => needed.some(r => matches(r, u))).length;
  return { h, pantry, needed, have, missing, usedUser, nameScore: 0, overlap: 0 };
};
const pack = a => ({
  name: a.h.payload.name, minutes: a.h.payload.minutes, steps: a.h.payload.steps || [],
  ingredient_lines: a.h.payload.ingredient_lines || null,
  cuisine_type: a.h.payload.cuisine_type || null,
  calories_per_serving: a.h.payload.calories_per_serving,
  protein_g: a.h.payload.protein_g, carbs_g: a.h.payload.carbs_g, fat_g: a.h.payload.fat_g,
  image_url: a.h.payload.image_url || null,
  pantry: a.pantry, needed: a.needed, have: a.have, missing: a.missing, score: a.h.score
});

// ---- fuzzy title matching: catches transliteration variants (shakshuka / chakchouka)
const lev = (a, b) => {
  const m = a.length, k = b.length;
  if (!m) return k;
  if (!k) return m;
  let prev = [];
  for (let j = 0; j <= k; j++) prev[j] = j;
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= k; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[k];
};
const qt = [...new Set(toks(n.title_query || "").filter(t => t.length > 2))];
const nameScore = a => {
  if (!qt.length) return 0;
  const nameToks = toks(a.h.payload.name || "");
  const words = String(a.h.payload.name || "").toLowerCase().split(/[^a-z]+/).filter(Boolean);
  let hit = 0;
  for (const t of qt) {
    if (nameToks.includes(t)) { hit++; continue; }
    const tol = t.length >= 8 ? 3 : 2;
    if (t.length > 4 && words.some(w => w.length > 4 && lev(w, t) <= tol)) hit++;
  }
  return hit / qt.length;
};

let ranked = [];
if (n.mode === "ingredients" && user.length) {
  const all = hits.map(analyse);
  const minUsed = Math.min(2, user.length);
  let pool = all.filter(a => a.usedUser >= minUsed && a.needed.length >= 3);
  if (!pool.length) pool = all.filter(a => a.usedUser >= 1);
  if (!pool.length) pool = all;
  ranked = pool.sort((a, b) => (a.missing.length - b.missing.length)
    || (b.usedUser - a.usedUser) || ((b.h.score || 0) - (a.h.score || 0)));
} else {
  ranked = hits.map(analyse);
  ranked.forEach(a => {
    a.nameScore = nameScore(a);
    a.overlap = doc && a.needed.length ? a.have.length / a.needed.length : 0;
  });
  const s = a => a.nameScore * (doc ? 2 : 1) + a.overlap;
  ranked.sort((a, b) => (s(b) - s(a)) || ((b.h.score || 0) - (a.h.score || 0)));
  if (!doc) ranked.forEach(a => { a.have = []; a.missing = []; });
}

const best = ranked[0];
let match = "n/a";
if (best && n.mode !== "ingredients") {
  match = (best.nameScore >= 0.67 || (doc && best.overlap >= 0.6)) ? "good"
    : (best.nameScore > 0 || (doc && best.overlap >= 0.3) || (best.h.score || 0) >= 0.78) ? "partial" : "weak";
}
const chosen = best ? pack(best) : null;
const alternatives = ranked.slice(1, 3).map(a => ({ name: a.h.payload.name, missing: a.missing.length, minutes: a.h.payload.minutes }));

const p = n.parsed || null;
const L = [];
L.push("MODE: " + n.mode);
if (doc && p) {
  L.push("User's own recipe title: " + (p.title || "unknown"));
  L.push("User's recipe ingredients: " + p.ingredients.slice(0, 20).join("; "));
  L.push("User's recipe steps: " + p.steps.slice(0, 6).map(x => String(x).slice(0, 140)).join(" | ").slice(0, 700));
  L.push(chosen ? "Similar knowledge-base recipe (reference only): " + chosen.name + (chosen.minutes ? " (" + chosen.minutes + " min)" : "") : "Similar knowledge-base recipe: none");
} else if (chosen) {
  L.push("Recipe: " + chosen.name + (chosen.minutes ? " (" + chosen.minutes + " min)" : ""));
  L.push("Recipe ingredients: " + chosen.needed.concat(chosen.pantry).slice(0, 25).join(", "));
  L.push("Recipe steps (first ones): " + chosen.steps.slice(0, 6).map(x => String(x).slice(0, 140)).join(" | ").slice(0, 700));
  if (chosen.calories_per_serving) L.push("Nutrition per serving: " + chosen.calories_per_serving + " kcal, "
    + (chosen.protein_g != null ? chosen.protein_g + " g protein" : "?") + ", "
    + (chosen.carbs_g != null ? chosen.carbs_g + " g carbs" : "?") + ", "
    + (chosen.fat_g != null ? chosen.fat_g + " g fat" : "?"));
}
const ing = n.mode === "ingredients";
L.push("User has: " + (ing && (n.user_ingredients || []).length ? n.user_ingredients.join(", ") : "NONE"));
L.push("Missing: " + (ing && chosen && chosen.missing.length ? chosen.missing.join(", ") : "NONE"));
L.push("Vegetarian requested: " + (n.vegetarian ? "yes" : "no"));

return [{ json: {
  mode: n.mode, source: n.source || "", query: n.query, title_query: n.title_query || "",
  user_ingredients: n.user_ingredients || [], uncertain: n.uncertain || [],
  vegetarian: !!n.vegetarian, max_minutes: n.max_minutes || null, max_calories: n.max_calories || null,
  cuisine:n.cuisine || null,min_protein:n.min_protein || null,
  parsed: p, detected_alternatives: n.alternatives || [],
  chosen, alternatives, retrieved: hits.length, match,
  retrieval_attempts:n.retrieval_attempts || 1, original_query:n.original_query || n.query,
  matched_ingredient_count: best ? best.usedUser : 0, title_overlap: best ? best.nameScore : 0,
  chef_context: L.join("\n")
}, pairedItem:{item:0} }];

const r=$json;
const c=r.chosen;
const a=r.approved || {intro:'',tip:'',substitutions:[]};
const p=r.parsed;
const isDoc=r.mode==='document' && p;
const title=isDoc?(p.title || 'Recipe from your image'):(c?.name || 'Recipe');
const ingredients=isDoc?(p.ingredients || []):(c?.ingredient_lines?.length ? c.ingredient_lines : (c?.needed || []).concat(c?.pantry || []));
const steps=isDoc?(p.steps || []):(c?.steps || []);
const lines=[title];
if (a.intro)lines.push(a.intro);
if (isDoc && p.complete!==true)lines.push('Some text in the image may be incomplete; check the original.');
lines.push('Ingredients:',...ingredients.map(s=>'- '+s),'Steps:',...steps.map((s,i)=>(i+1)+'. '+s));
if (a.tip)lines.push('Tip: '+a.tip);
if ((a.substitutions || []).length)lines.push('Optional substitutions:',...a.substitutions.map(s=>s.missing+' -> '+s.replace_with));
return [{json:{...r,answer:lines.join('\n'),approved:a,validation_status:r.validation_passed?'passed':'filtered',
  chosen_name:c?.name || null,match:r.match || 'n/a'}}];

