const r=$('Prepare chef input').item.json;
let o={};try {o=JSON.parse($json.message.content || '{}');}catch(_){}
const strip=s=>String(s||'').replace(/[*_`#\[\]]/g,'').replace(/\s+/g,' ').trim();
const clip=(s,max)=>strip(s).slice(0,max);
const norm=s=>strip(s).toLowerCase();
const allowed=r.mode==='ingredients' && r.chosen ? (r.chosen.missing || []) : [];
const whitelist=new Set(allowed.map(norm));
const seen=new Set();
const subs=(Array.isArray(o.substitutions)?o.substitutions:[])
 .filter(s=>s && typeof s==='object' && whitelist.has(norm(s.missing)) && strip(s.replace_with)
   && norm(s.missing)!==norm(s.replace_with) && !seen.has(norm(s.missing)) && seen.add(norm(s.missing)))
 .slice(0,3).map(s=>({missing:strip(s.missing),replace_with:clip(s.replace_with,120)}));
let chef={intro:clip(o.intro,220),tip:clip(o.tip,200),substitutions:subs};
if (r.chef_attempt > 1) {
 const a=r.approved || {intro:'',tip:'',substitutions:[]};
 const issues=r.validation_issues || {intro:'',tip:'',substitutions:[]};
 const used=new Set();
 const keep=[];
 for(const s of (a.substitutions || []).concat(subs)) {
   const k=norm(s.missing);
   if(!k || used.has(k) || !whitelist.has(k))continue;
   used.add(k);keep.push(s);
 }
 chef={intro:issues.intro?chef.intro:a.intro,
       tip:issues.tip?chef.tip:a.tip,
       substitutions:keep.slice(0,3)};
}
return [{json:{...r,chef,validator_input:(r.chef_context || '')+'\n\nOutput to check:\n'+JSON.stringify(chef)},pairedItem:{item:0}}];

const q=$('Has query').first().json;
const text=String($('Webhook').first().json.body.query || '').trim();
return [{json:{error: q.mode==='help' ? 'I can suggest recipes from your ingredients, a dish name, or a food/recipe photo.' :
  (text ? 'I could not identify a searchable recipe request.' : 'I could not detect any ingredients or request. Type what you have or upload a photo.')}}];

const f=$json;
const r=f;
const p=r.parsed || null;
const c=r.chosen || null;
const safe=f.approved || {intro:'',tip:'',substitutions:[]};
const note=[safe.intro,safe.tip].filter(Boolean).join(' ');
if (r.mode==='document' && p){
 return [{json:{
  name:p.title || 'Recipe from your image',minutes:null,kcal:null,protein_g:null,carbs_g:null,fat_g:null,
  ingredients:p.ingredients || [],steps:p.steps || [],servings:p.servings || null,recipe_time:p.time || null,
  complete:p.complete===true,language:p.language || null,cuisine_type:null,
  vegetarian:!!r.vegetarian,image_url:null,chef_note:note,substitutions:safe.substitutions || [],
  kb_match:c?.name || null,validation_status:r.validation_status,
  retrieval_attempts:r.retrieval_attempts || 1,chef_attempts:r.chef_attempt || 1
 }}];
}
if (!c) return [{json:{error:'No matching recipe was found. Try other ingredients, a different dish name, or relax the filters.'}}];
return [{json:{
 name:c.name, minutes:c.minutes ?? null,
 kcal:c.calories_per_serving ?? null, protein_g:c.protein_g ?? null,
 carbs_g:c.carbs_g ?? null,fat_g:c.fat_g ?? null,
 ingredients:c.ingredient_lines?.length ? c.ingredient_lines : (c.needed || []).concat(c.pantry || []),
 steps:(c.steps || []).slice(0,20),cuisine_type:c.cuisine_type || null,
 vegetarian:!!r.vegetarian, image_url:c.image_url || null,
 chef_note:note,substitutions:safe.substitutions || [],
 have:c.have || [],missing:c.missing || [],pantry:c.pantry || [],
 match:r.match || 'n/a',validation_status:r.validation_status,
 retrieval_attempts:r.retrieval_attempts || 1,chef_attempts:r.chef_attempt || 1
}}];

const j=$json;
const stage=j.validation_issues!==undefined && j.validation_issues!==null ? 'validation':'retrieval';
let allowed=[];
if(stage==='retrieval'){
  allowed=(j.retrieval_attempts || 1)<2 ? ['retry_retrieval','stop']:['stop'];
}else if(j.retrieval_issue){
  allowed=(j.retrieval_attempts || 1)<2 ? ['retry_retrieval','stop']:['stop'];
}else if(j.should_revise && (j.chef_attempt || 1)<2){
  allowed=['revise_chef','finalize'];
}else{
  allowed=['finalize'];
}
const facts={stage,allowed,
 query:j.query,original_query:j.original_query || j.query,
 mode:j.mode,requested_title:j.title_query || '',
 user_ingredients:(j.user_ingredients || []).slice(0,20),
 retrieved:j.retrieved || 0,chosen_recipe:j.chosen?.name || null,
 match:j.match || 'n/a',quality_reason:j.quality_reason || null,
 filters:{max_minutes:j.max_minutes || null,max_calories:j.max_calories || null,
 vegetarian:!!j.vegetarian,cuisine:j.cuisine || null,min_protein:j.min_protein || null},
 validation_issues:j.validation_issues || null,
 retrieval_issue:!!j.retrieval_issue,retrieval_reason:j.retrieval_reason || '',
 retrieval_attempts:j.retrieval_attempts || 1,chef_attempt:j.chef_attempt || 0};
return [{json:{stage,allowed,facts,state:j},pairedItem:{item:0}}];

const context=$('Agent state').item.json;
let o={};try{o=JSON.parse($json.message.content || '{}');}catch(_){}
const s=context.state;
const compact=t=>String(t || '').replace(/[\x00-\x1f]/g,' ').replace(/\s+/g,' ').trim().slice(0,180);
const old=compact(s.query),alternative=compact(o.query);
let action=context.allowed.includes(o.action)?o.action:'';
if(action==='retry_retrieval'){
 if(s.retrieval_attempts>=2 || alternative.length<3 || alternative.toLowerCase()===old.toLowerCase())
   action=s.chosen && !s.retrieval_issue ? 'finalize':'stop';
}
// Keep model output inside strict state-machine bounds.
if(!context.allowed.includes(action))
 action=context.stage==='validation'&&!s.retrieval_issue?'finalize':'stop';
return [{json:{...s,query:action==='retry_retrieval'?alternative:old,
 __action:action,agent_reason:compact(o.reason),
 last_supervisor_stage:context.stage},pairedItem:{item:0}}];

const r = $json;
const hasParsed = r.mode === 'document' && r.parsed && (r.parsed.ingredients?.length > 0 || r.parsed.steps?.length > 0);
const matchIngredients = r.mode === 'ingredients' && r.chosen && r.matched_ingredient_count > 0;
const matchDish = (r.mode === 'dish' || r.mode === 'text') && r.chosen && (r.match === 'good' || r.match === 'partial');
const retrieval_ok = !!(hasParsed || matchIngredients || matchDish);
return [{json:{...r, retrieval_ok, quality_reason: hasParsed ? 'original_document' : matchIngredients ? 'ingredient_overlap' : matchDish ? 'recipe_match' : 'weak_or_missing'},pairedItem:{item:0}}];

const r=$json;
const attempt=Math.max(0,Math.min(1,Number(r.chef_attempt || 0)))+1;
return [{json:{...r,chef_attempt:attempt,retrieval_attempts:r.retrieval_attempts || 1},pairedItem:{item:0}}];

const previous=$('Parse chef').item.json;
let v={};let parseOk=true;
try{v=JSON.parse($json.message.content || '{}');}catch(_){parseOk=false;}
const src=previous.chef || {intro:'',tip:'',substitutions:[]};
const verdictIsGood= parseOk && v && typeof v==='object' &&
  v.retrieval && typeof v.retrieval.ok==='boolean' &&
  v.intro && typeof v.intro.ok==='boolean' && v.tip && typeof v.tip.ok==='boolean' &&
  Array.isArray(v.substitutions) && v.substitutions.length===src.substitutions.length &&
  v.substitutions.every(x=>x && typeof x.ok==='boolean');
const nonveg=/\b(chicken|beef|pork|lamb|veal|bacon|ham|sausage|salami|fish|tuna|salmon|anchov\w*|shrimp|prawn\w*|gelatin\w*|lard|meat\w*|turkey|duck|animal|bone)\b/i;
const decision=(ok,why)=>({ok,reason:ok?'':String(why||'failed verification').slice(0,180)});
const introOK=!!(verdictIsGood && (!src.intro || v.intro.ok===true));
const tipOK=!!(verdictIsGood && (!src.tip || v.tip.ok===true));
const subsStatus=src.substitutions.map((s,i)=>{
 const allowed=verdictIsGood && v.substitutions[i].ok===true &&
  !(previous.vegetarian && nonveg.test(s.replace_with));
 return decision(!!allowed, allowed?'':(verdictIsGood?v.substitutions[i].reason:'validator unavailable or malformed'));
});
const introReason=introOK?'':(verdictIsGood?v.intro.reason:'validator unavailable or malformed');
const tipReason=tipOK?'':(verdictIsGood?v.tip.reason:'validator unavailable or malformed');
const approved={
 intro:introOK?src.intro:'',tip:tipOK?src.tip:'',
 substitutions:src.substitutions.filter((_,i)=>subsStatus[i].ok)
};
const issues={
 intro:src.intro && !introOK ? String(introReason || 'unsupported introduction') : '',
 tip:src.tip && !tipOK ? String(tipReason || 'unsupported tip') : '',
 substitutions:src.substitutions.filter((s,i)=>!subsStatus[i].ok).map((s,i)=>({missing:s.missing,replace_with:s.replace_with,reason:subsStatus[src.substitutions.indexOf(s)]?.reason || 'not acceptable'}))
};
const retrievalVerdict=verdictIsGood && v.retrieval && typeof v.retrieval.ok==='boolean';
const retrieval_issue=previous.mode!=='document' && !!(retrievalVerdict && v.retrieval.ok===false);
const retrieval_reason=retrieval_issue?String(v.retrieval.reason || 'recipe mismatch').slice(0,180):'';
const rejected=!!(issues.intro || issues.tip || issues.substitutions.length);
return [{json:{...previous,approved,validation_issues:issues,validator_valid:!!verdictIsGood,
  retrieval_issue,retrieval_reason,
  validation_passed:!!verdictIsGood && !rejected && !retrieval_issue, should_revise:(previous.chef_attempt || 1)<2 && rejected && !!verdictIsGood,
  chef_attempt:previous.chef_attempt || 1},pairedItem:{item:0}}];

const r=$json;
const feedback={trusted_context:r.chef_context,previous_output:r.chef,
 validation_issues:r.validation_issues,approved_fields:r.approved,
 instructions:'Fix only rejected fields. Keep approved fields unchanged. Return full JSON.'};
return [{json:{...r,revision_context:JSON.stringify(feedback)},pairedItem:{item:0}}];

const j=$json;
const attempts=Math.max(0,Math.min(2,Number(j.retrieval_attempts || 0)))+1;
const query=String(j.query || '').replace(/[\r\n]/g,' ').trim();
return [{json:{...j,query,original_query:j.original_query || query,
  retrieval_attempts:attempts,
  chef_attempt:0,chef:null,approved:null,validation_issues:null,
  validator_valid:null,should_revise:null},pairedItem:{item:0}}];
